import{_ as t,c as s,o as i,a2 as e}from"./chunks/framework.PGES7OoM.js";const d=JSON.parse('{"title":"authenticateAccount","description":"Login/register facade for application state: returns only a safe profile, retaining keys in the config.","frontmatter":{"editLink":false,"rawMarkdown":"# authenticateAccount\\n\\nLogin/register facade for application state: returns only a safe profile, retaining keys in the config.\\n\\n## Import\\n\\n```ts\\nimport { authenticateAccount } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await authenticateAccount({ action, credential, config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction authenticateAccount(parameters: AuthenticateAccountParameters): Promise<AccountProfile>\\n```\\n\\n## Returns\\n\\n`Promise<Readonly<{ id: string; createdAt: number | null; ownerAddress: string | null; curvyHandle: CurvyId | null; capabilities: AccountCapabilities; }>>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `action`\\n\\n- **Type:** `\\"login\\" | \\"register\\"`\\n- **Required:** yes\\n\\nWhether to `\\"login\\"` to an existing account or `\\"register\\"` a new one.\\n\\n```ts\\nconst result = await authenticateAccount({\\n  action, // [!code focus]\\n  credential,\\n});\\n```\\n\\n### `credential`\\n\\n- **Type:** `\\"signature\\" | \\"privateKeys\\" | \\"passkey\\"`\\n- **Required:** yes\\n\\nThe credential kind the remaining parameters describe: `\\"signature\\"`, `\\"privateKeys\\"` or `\\"passkey\\"`.\\n\\n```ts\\nconst result = await authenticateAccount({\\n  action,\\n  credential, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await authenticateAccount({\\n  action,\\n  credential,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Authentication guide](/for-programmers/authentication)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/auth/authenticateAccount.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/auth/authenticateAccount.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/auth/authenticateAccount.md","rawMarkdownTitle":"authenticateAccount","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/auth/authenticateAccount.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"auth","action":"authenticateAccount"},"relativePath":"sdk/actions/auth/authenticateAccount.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/auth/authenticateAccount.md"};function r(o,a,c,l,h,p){return i(),s("div",null,[...a[0]||(a[0]=[e("",30)])])}const k=t(n,[["render",r]]);export{d as __pageData,k as default};
